import * as THREE from 'three';

export interface RendererOptions {
  antialias?: boolean;
  alpha?: boolean;
  powerPreference?: WebGLPowerPreference;
  maxPixelRatio?: number;
  enableShadows?: boolean;
  shadowMapType?: THREE.ShadowMapType;
  toneMappingExposure?: number;
}

export interface RenderSize {
  width: number;
  height: number;
}

export type ContextRecoveryListener = (renderer: THREE.WebGLRenderer) => void;

/**
 * Owns the Three.js WebGL renderer and the small amount of global GPU state
 * shared by the game. The class deliberately has no dependency on gameplay,
 * courses or external assets so it can recover from a lost WebGL context.
 */
export class Renderer {
  readonly renderer: THREE.WebGLRenderer;

  private readonly maxPixelRatio: number;
  private readonly recoveryListeners = new Set<ContextRecoveryListener>();
  private readonly geometries = new Map<string, THREE.BufferGeometry>();
  private readonly materials = new Map<string, THREE.Material>();
  private lost = false;
  private disposed = false;

  constructor(options: RendererOptions = {}) {
    this.maxPixelRatio = Math.max(1, options.maxPixelRatio ?? 2);

    this.renderer = new THREE.WebGLRenderer({
      antialias: options.antialias ?? true,
      alpha: options.alpha ?? false,
      powerPreference: options.powerPreference ?? 'high-performance',
    });

    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = options.toneMappingExposure ?? 1;
    this.renderer.shadowMap.enabled = options.enableShadows ?? true;
    this.renderer.shadowMap.type = options.shadowMapType ?? THREE.PCFSoftShadowMap;

    this.updatePixelRatio();
    this.renderer.domElement.addEventListener('webglcontextlost', this.handleContextLost, false);
    this.renderer.domElement.addEventListener('webglcontextrestored', this.handleContextRestored, false);
  }

  get canvas(): HTMLCanvasElement {
    return this.renderer.domElement;
  }

  get isContextLost(): boolean {
    return this.lost || this.renderer.getContext().isContextLost();
  }

  setSize(width: number, height: number, updateStyle = true): RenderSize {
    const safeWidth = Math.max(1, Math.floor(width));
    const safeHeight = Math.max(1, Math.floor(height));
    this.renderer.setSize(safeWidth, safeHeight, updateStyle);
    return { width: safeWidth, height: safeHeight };
  }

  resizeToElement(element: HTMLElement, updateStyle = false): RenderSize {
    return this.setSize(element.clientWidth, element.clientHeight, updateStyle);
  }

  updatePixelRatio(devicePixelRatio = globalThis.devicePixelRatio ?? 1): number {
    const ratio = Math.min(Math.max(1, devicePixelRatio), this.maxPixelRatio);
    this.renderer.setPixelRatio(ratio);
    return ratio;
  }

  render(scene: THREE.Scene, camera: THREE.Camera): void {
    if (this.disposed || this.isContextLost) return;
    this.renderer.render(scene, camera);
  }

  setAnimationLoop(callback: XRFrameRequestCallback | null): void {
    this.renderer.setAnimationLoop(callback);
  }

  onContextRestored(listener: ContextRecoveryListener): () => void {
    this.recoveryListeners.add(listener);
    return () => this.recoveryListeners.delete(listener);
  }

  /** Shared geometry cache for obstacle/course renderers and future instancing. */
  getOrCreateGeometry<T extends THREE.BufferGeometry>(key: string, factory: () => T): T {
    const existing = this.geometries.get(key);
    if (existing) return existing as T;
    const created = factory();
    this.geometries.set(key, created);
    return created;
  }

  /** Shared material cache for low-poly course pieces and future instancing. */
  getOrCreateMaterial<T extends THREE.Material>(key: string, factory: () => T): T {
    const existing = this.materials.get(key);
    if (existing) return existing as T;
    const created = factory();
    this.materials.set(key, created);
    return created;
  }

  createInstancedMesh(
    geometry: THREE.BufferGeometry,
    material: THREE.Material,
    count: number,
  ): THREE.InstancedMesh {
    const mesh = new THREE.InstancedMesh(geometry, material, Math.max(1, Math.floor(count)));
    mesh.castShadow = this.renderer.shadowMap.enabled;
    mesh.receiveShadow = this.renderer.shadowMap.enabled;
    return mesh;
  }

  clearSharedResources(): void {
    for (const geometry of this.geometries.values()) geometry.dispose();
    for (const material of this.materials.values()) material.dispose();
    this.geometries.clear();
    this.materials.clear();
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.renderer.setAnimationLoop(null);
    this.canvas.removeEventListener('webglcontextlost', this.handleContextLost);
    this.canvas.removeEventListener('webglcontextrestored', this.handleContextRestored);
    this.recoveryListeners.clear();
    this.clearSharedResources();
    this.renderer.dispose();
  }

  private readonly handleContextLost = (event: Event): void => {
    event.preventDefault();
    this.lost = true;
  };

  private readonly handleContextRestored = (): void => {
    this.lost = false;
    this.renderer.resetState();
    this.updatePixelRatio();
    for (const listener of this.recoveryListeners) listener(this.renderer);
  };
}
