import * as THREE from 'three';

export interface SceneTheme {
  background: THREE.ColorRepresentation;
  fog: THREE.ColorRepresentation;
  fogNear: number;
  fogFar: number;
  hemisphereSky: THREE.ColorRepresentation;
  hemisphereGround: THREE.ColorRepresentation;
  hemisphereIntensity: number;
  sunColor: THREE.ColorRepresentation;
  sunIntensity: number;
}

export interface SceneManagerOptions {
  theme?: Partial<SceneTheme>;
  shadows?: boolean;
  shadowMapSize?: number;
  shadowCameraExtent?: number;
}

const DEFAULT_THEME: SceneTheme = {
  background: 0x88bde6,
  fog: 0x88bde6,
  fogNear: 35,
  fogFar: 105,
  hemisphereSky: 0xcfe9ff,
  hemisphereGround: 0x6f8054,
  hemisphereIntensity: 1.6,
  sunColor: 0xfff3d6,
  sunIntensity: 2.4,
};

/**
 * Scene-level infrastructure: a stylized low-poly light rig, fog and roots for
 * static/dynamic/transient content. It is intentionally asset-free.
 */
export class SceneManager {
  readonly scene = new THREE.Scene();
  readonly worldRoot = new THREE.Group();
  readonly dynamicRoot = new THREE.Group();
  readonly transientRoot = new THREE.Group();
  readonly lightsRoot = new THREE.Group();
  readonly hemisphereLight: THREE.HemisphereLight;
  readonly sunLight: THREE.DirectionalLight;

  private theme: SceneTheme;

  constructor(options: SceneManagerOptions = {}) {
    this.theme = { ...DEFAULT_THEME, ...options.theme };

    this.worldRoot.name = 'world';
    this.dynamicRoot.name = 'dynamic';
    this.transientRoot.name = 'transient';
    this.lightsRoot.name = 'lights';

    this.scene.add(this.worldRoot, this.dynamicRoot, this.transientRoot, this.lightsRoot);

    this.hemisphereLight = new THREE.HemisphereLight(
      this.theme.hemisphereSky,
      this.theme.hemisphereGround,
      this.theme.hemisphereIntensity,
    );
    this.hemisphereLight.name = 'hemisphere-fill';

    this.sunLight = new THREE.DirectionalLight(this.theme.sunColor, this.theme.sunIntensity);
    this.sunLight.name = 'sun';
    this.sunLight.position.set(18, 30, 12);
    this.sunLight.castShadow = options.shadows ?? true;

    const shadowMapSize = Math.max(256, options.shadowMapSize ?? 1024);
    this.sunLight.shadow.mapSize.set(shadowMapSize, shadowMapSize);
    this.sunLight.shadow.bias = -0.00035;
    this.sunLight.shadow.normalBias = 0.025;

    const extent = Math.max(8, options.shadowCameraExtent ?? 28);
    const shadowCamera = this.sunLight.shadow.camera;
    shadowCamera.left = -extent;
    shadowCamera.right = extent;
    shadowCamera.top = extent;
    shadowCamera.bottom = -extent;
    shadowCamera.near = 1;
    shadowCamera.far = 90;

    this.lightsRoot.add(this.hemisphereLight, this.sunLight, this.sunLight.target);
    this.applyTheme();
  }

  setTheme(theme: Partial<SceneTheme>): void {
    this.theme = { ...this.theme, ...theme };
    this.applyTheme();
  }

  setSunTarget(position: THREE.Vector3 | THREE.Vector3Tuple): void {
    if (Array.isArray(position)) {
      this.sunLight.target.position.fromArray(position);
    } else {
      this.sunLight.target.position.copy(position);
    }
    this.sunLight.target.updateMatrixWorld();
  }

  addStatic<T extends THREE.Object3D>(object: T): T {
    this.worldRoot.add(object);
    return object;
  }

  addDynamic<T extends THREE.Object3D>(object: T): T {
    this.dynamicRoot.add(object);
    return object;
  }

  addTransient<T extends THREE.Object3D>(object: T): T {
    this.transientRoot.add(object);
    return object;
  }

  clearWorld(disposeResources = false): void {
    this.clearGroup(this.worldRoot, disposeResources);
    this.clearGroup(this.dynamicRoot, disposeResources);
    this.clearGroup(this.transientRoot, disposeResources);
  }

  clearTransient(disposeResources = false): void {
    this.clearGroup(this.transientRoot, disposeResources);
  }

  dispose(): void {
    this.clearWorld(true);
    this.scene.remove(this.worldRoot, this.dynamicRoot, this.transientRoot, this.lightsRoot);
    this.lightsRoot.clear();
  }

  private applyTheme(): void {
    this.scene.background = new THREE.Color(this.theme.background);
    this.scene.fog = new THREE.Fog(this.theme.fog, this.theme.fogNear, this.theme.fogFar);
    this.hemisphereLight.color.set(this.theme.hemisphereSky);
    this.hemisphereLight.groundColor.set(this.theme.hemisphereGround);
    this.hemisphereLight.intensity = this.theme.hemisphereIntensity;
    this.sunLight.color.set(this.theme.sunColor);
    this.sunLight.intensity = this.theme.sunIntensity;
  }

  private clearGroup(group: THREE.Group, disposeResources: boolean): void {
    const children = [...group.children];
    for (const child of children) {
      group.remove(child);
      if (disposeResources) this.disposeObjectResources(child);
    }
  }

  private disposeObjectResources(root: THREE.Object3D): void {
    root.traverse((object) => {
      const mesh = object as THREE.Mesh;
      if (!mesh.isMesh) return;

      mesh.geometry?.dispose();
      const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
      for (const material of materials) material?.dispose();
    });
  }
}
